def main():
    text = open(SRC, encoding='utf-8').read()
    lines = text.split('\n')
    mp = {}
    for old, new in PAIRS:
        if old in mp:
            print('DUPLICATE KEY:', old[:60], file=sys.stderr)
            sys.exit(1)
        mp[old] = new

    changed = 0
    missing = []
    seen = set()
    out = []
    for line in lines:
        st = line.strip()
        if st in mp:
            indent = line[:len(line) - len(line.lstrip())]
            out.append(indent + mp[st])
            changed += 1
            seen.add(st)
        else:
            out.append(line)

    for old in mp:
        if old not in seen:
            missing.append(old)

    if missing:
        print('MISSING KEYS (%d):' % len(missing), file=sys.stderr)
        for m in missing:
            print('  ', m[:120], file=sys.stderr)
        sys.exit(2)

    result = '\n'.join(out)
    open(DST, 'w', encoding='utf-8').write(result)
    print('pairs:', len(PAIRS), 'lines changed:', changed, 'bytes:', len(result.encode('utf-8')))


if __name__ == '__main__':
    main()
